package com.careerpilot.modules.interview.entity;
import com.careerpilot.modules.auth.entity.User;import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.*;
@Entity@Table(name="interview_sessions")@Getter@Setter@NoArgsConstructor public class InterviewSession{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@Column(name="target_career",nullable=false,length=120)private String targetCareer;@Column(name="interview_type",nullable=false,length=30)private String interviewType;@Enumerated(EnumType.STRING)@Column(nullable=false,length=10)private InterviewMode mode;@Column(name="focus_area",length=120)private String focusArea;@Column(name="question_count",nullable=false)private int questionCount;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private InterviewStatus status;@Column(name="current_question",nullable=false,columnDefinition="TEXT")private String currentQuestion;@Column(name="completed_answers",nullable=false)private int completedAnswers;@Column(name="overall_coaching_score")private Integer overallCoachingScore;@Column(length=40)private String provider;@Column(length=120)private String model;@Column(name="started_at",nullable=false)private Instant startedAt;@Column(name="completed_at")private Instant completedAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@OneToMany(mappedBy="session",cascade=CascadeType.ALL,orphanRemoval=true)@OrderBy("sequenceNumber")private List<InterviewAnswer>answers=new ArrayList<>();@PrePersist void create(){if(id==null)id=UUID.randomUUID();var now=Instant.now();if(startedAt==null)startedAt=now;updatedAt=now;if(status==null)status=InterviewStatus.IN_PROGRESS;}@PreUpdate void update(){updatedAt=Instant.now();}}
